-- Breakfast fees (15 Nov 2026, Ahmed — DECISIONS.md 2026-11-15 «Breakfast fees»). Generated by scripts/breakfast-migration.mjs.
-- Settings is the source: adult 25 SAR per person per day incl. VAT; children up to 6 free, up to 12 SAR 12.50, above 12
-- the adult price. The texts are generated from Settings, never typed:
--   1. site_fees() also returns breakfast_child_tiers (the build writes it to content/fees.generated.json);
--   2. internal.hub_fill_fees (the assistant's FAQ read) fills {breakfast_free_age}, {breakfast_child_age} and
--      {breakfast_child} by the same rule as the site (src/lib/content.ts → breakfastChildren);
--   3. internal.copy_problems accepts the three placeholders (the dashboard's FAQ and content editors);
--   4. the published FAQ answer «breakfast» and the content field policy.guests.body (seed and draft) take the new texts
--      of content/faq.json and content/policies.json. One audit batch. No unit mode, licence or switch changes.

create or replace function public.site_fees() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'breakfast_adult', (select (s.value ->> 'adult')::numeric from public.settings s where s.key = 'breakfast'),
    'extra_bed_per_night', (select (s.value #>> '{}')::numeric from public.settings s where s.key = 'extra_bed_per_night'),
    -- the children's breakfast (15 Nov 2026): [{max_age, price}] — the texts are generated from it, never typed
    'breakfast_child_tiers', (select s.value -> 'child_tiers' from public.settings s where s.key = 'breakfast'))
$$;

create or replace function internal.hub_fill_fees(p text, p_lang text) returns text
language sql stable security definer set search_path = '' as $$
  with f as (select public.site_fees() as j),
       t as (select (x ->> 'max_age')::numeric as age, (x ->> 'price')::numeric as price
               from f, jsonb_array_elements(coalesce(f.j -> 'breakfast_child_tiers', '[]'::jsonb)) x),
       k as (select (select max(age) from t where price = 0) as free_age,
                    (select age from t where price > 0 order by age limit 1) as child_age,
                    (select price from t where price > 0 order by age limit 1) as child_price)
  select replace(replace(replace(replace(replace(coalesce(p, ''),
    '{breakfast}', coalesce(internal.hub_sar_text((f.j ->> 'breakfast_adult')::numeric, p_lang), '{breakfast}')),
    '{extra_bed}', coalesce(internal.hub_sar_text((f.j ->> 'extra_bed_per_night')::numeric, p_lang), '{extra_bed}')),
    '{breakfast_free_age}', coalesce(k.free_age::bigint::text, '{breakfast_free_age}')),
    '{breakfast_child_age}', coalesce(k.child_age::bigint::text, '{breakfast_child_age}')),
    '{breakfast_child}', coalesce(internal.hub_sar_text(k.child_price, p_lang), '{breakfast_child}'))
    from f, k
$$;

create or replace function internal.copy_problems(p_ar text, p_en text, p_max integer, p_keep text[] default '{}', p_need jsonb default '{}'::jsonb) returns jsonb
language plpgsql immutable set search_path = '' as $$
declare
  v_out jsonb := '[]'::jsonb;
  l text;
  t text;
  v_term text;
  v_ph text;
  v_alt jsonb;
begin
  foreach l in array array['ar', 'en'] loop
    t := coalesce(case l when 'ar' then p_ar else p_en end, '');
    if btrim(t) = '' then
      v_out := v_out || jsonb_build_object('code', 'required', 'lang', l);
      continue;
    end if;
    if char_length(t) > p_max then v_out := v_out || jsonb_build_object('code', 'too_long', 'lang', l, 'max', p_max); end if;
    -- brand policy (CLAUDE.md §4): never for an Armada property
    foreach v_term in array array['شقق مخدومة', 'شقة مخدومة', 'serviced apartment', 'armada café', 'armada cafe', 'خدمة الغرف', 'room service'] loop
      if strpos(lower(t), v_term) > 0 then v_out := v_out || jsonb_build_object('code', 'forbidden_term', 'lang', l, 'term', v_term); end if;
    end loop;
    -- each required term is a string, or an array of accepted forms (the Arabic case endings: «شقق فندقية» / «شققًا فندقية»)
    for v_alt in select e from jsonb_array_elements(coalesce(p_need -> l, '[]'::jsonb)) e loop
      if not exists (select 1 from jsonb_array_elements_text(case jsonb_typeof(v_alt) when 'array' then v_alt else jsonb_build_array(v_alt) end) a
                      where strpos(lower(t), lower(a)) > 0) then
        v_out := v_out || jsonb_build_object('code', 'required_term', 'lang', l,
                                             'term', case jsonb_typeof(v_alt) when 'array' then v_alt ->> 0 else v_alt #>> '{}' end);
      end if;
    end loop;
    foreach v_ph in array coalesce(p_keep, '{}') loop
      if strpos(t, '{' || v_ph || '}') = 0 then v_out := v_out || jsonb_build_object('code', 'placeholder_removed', 'lang', l, 'name', v_ph); end if;
    end loop;
    foreach v_ph in array internal.copy_placeholders(t) loop
      if v_ph not in ('breakfast', 'extra_bed', 'breakfast_free_age', 'breakfast_child_age', 'breakfast_child', 'shafa_opened', 'airport_opened', 'shafa_units', 'airport_units', 'airport_minutes', 'shafa_room_min', 'airport_room_min', 'suite_max') then v_out := v_out || jsonb_build_object('code', 'placeholder_unknown', 'lang', l, 'name', v_ph); end if;
    end loop;
    -- the site writes Western digits everywhere
    if t ~ '[٠-٩۰-۹]' then v_out := v_out || jsonb_build_object('code', 'indic_digits', 'lang', l); end if;
    -- a room rate is never typed (prices come from the dashboard at runtime); fees use the placeholders
    if t ~* '([0-9][0-9,.]*\s*(ريال|ر\.س|sar)|sar\s*[0-9])[^.؛\n]{0,40}(ليلة|night)'
       or t ~* '(ليلة|night)[^.؛\n]{0,20}([0-9][0-9,.]*\s*(ريال|ر\.س|sar)|sar\s*[0-9])' then
      v_out := v_out || jsonb_build_object('code', 'price_typed', 'lang', l);
    end if;
    -- phone numbers come from contact.json, never typed
    if t ~ '(\+?966[\s-]?5[0-9]|\y05[0-9]{8}\y|\y5[0-9]{8}\y)' then v_out := v_out || jsonb_build_object('code', 'phone_typed', 'lang', l); end if;
  end loop;
  if btrim(coalesce(p_ar, '')) <> '' and btrim(coalesce(p_en, '')) <> ''
     and internal.copy_placeholders(p_ar) is distinct from internal.copy_placeholders(p_en) then
    v_out := v_out || jsonb_build_object('code', 'placeholder_mismatch');
  end if;
  return v_out;
end;
$$;

do $bfm$
declare v_batch uuid := internal.begin_batch();
begin
  perform set_config('app.actor', 'Breakfast fees — migration, Ahmed''s brief of 15 Nov 2026', true);
  update public.faq_items
     set a_ar = $bf$الإفطار اختياري تختاره عند الحجز، ورسومه {breakfast} للشخص في اليوم شاملة الضريبة؛ والأطفال حتى {breakfast_free_age} سنوات مجانًا، ومن هم حتى {breakfast_child_age} سنة رسومهم {breakfast_child}، وفوق {breakfast_child_age} سنة بسعر البالغ. يُقدَّم بوفيه الإفطار يوميًا في مطعم كل فرع من 7:00 إلى 10:30 صباحًا.$bf$, a_en = $bf$Breakfast is optional and chosen when you book, at {breakfast} per person per day, VAT included; children up to {breakfast_free_age} eat free, children up to {breakfast_child_age} pay {breakfast_child}, and over {breakfast_child_age} the adult price. The breakfast buffet is served daily in each property's restaurant from 7:00 to 10:30 am.$bf$,
         live = case when live is not null then live || jsonb_build_object('a_ar', $bf$الإفطار اختياري تختاره عند الحجز، ورسومه {breakfast} للشخص في اليوم شاملة الضريبة؛ والأطفال حتى {breakfast_free_age} سنوات مجانًا، ومن هم حتى {breakfast_child_age} سنة رسومهم {breakfast_child}، وفوق {breakfast_child_age} سنة بسعر البالغ. يُقدَّم بوفيه الإفطار يوميًا في مطعم كل فرع من 7:00 إلى 10:30 صباحًا.$bf$, 'a_en', $bf$Breakfast is optional and chosen when you book, at {breakfast} per person per day, VAT included; children up to {breakfast_free_age} eat free, children up to {breakfast_child_age} pay {breakfast_child}, and over {breakfast_child_age} the adult price. The breakfast buffet is served daily in each property's restaurant from 7:00 to 10:30 am.$bf$) end
   where key = 'breakfast' and not is_test;
  update public.content_fields
     set seed_ar = $bf$يشمل سعر الغرفة والاستديو وجناح الغرفة والصالة شخصين بالغين، ويشمل سعر الأجنحة بغرفتي نوم أربعة. الأطفال لا يُحسبون ضمن العدد المشمول. السرير الإضافي {extra_bed} لليلة ويشمل الشخص الذي ينام عليه، ويتوفر في بعض أنواع الغرف وتختاره عند الحجز. يُقدَّم بوفيه إفطار يومي في مطعم كل فرع من 7:00 إلى 10:30 صباحًا؛ والإفطار اختياري تختاره عند الحجز، ورسومه {breakfast} للشخص في اليوم شاملة الضريبة؛ والأطفال حتى {breakfast_free_age} سنوات مجانًا، ومن هم حتى {breakfast_child_age} سنة رسومهم {breakfast_child}، وفوق {breakfast_child_age} سنة بسعر البالغ.$bf$, seed_en = $bf$Room, studio and one-bedroom suite prices cover two adults; two-bedroom suite prices cover four. Children are not counted toward the included number. An extra bed is {extra_bed} per night, covering whoever sleeps on it; it is available in selected room types and chosen when you book. A daily breakfast buffet is served in each property's restaurant 7:00–10:30 am; breakfast is optional and chosen when you book, at {breakfast} per person per day, VAT included; children up to {breakfast_free_age} eat free, children up to {breakfast_child_age} pay {breakfast_child}, and over {breakfast_child_age} the adult price.$bf$,
         draft_ar = case when draft_ar is null or draft_ar = seed_ar then $bf$يشمل سعر الغرفة والاستديو وجناح الغرفة والصالة شخصين بالغين، ويشمل سعر الأجنحة بغرفتي نوم أربعة. الأطفال لا يُحسبون ضمن العدد المشمول. السرير الإضافي {extra_bed} لليلة ويشمل الشخص الذي ينام عليه، ويتوفر في بعض أنواع الغرف وتختاره عند الحجز. يُقدَّم بوفيه إفطار يومي في مطعم كل فرع من 7:00 إلى 10:30 صباحًا؛ والإفطار اختياري تختاره عند الحجز، ورسومه {breakfast} للشخص في اليوم شاملة الضريبة؛ والأطفال حتى {breakfast_free_age} سنوات مجانًا، ومن هم حتى {breakfast_child_age} سنة رسومهم {breakfast_child}، وفوق {breakfast_child_age} سنة بسعر البالغ.$bf$ else draft_ar end,
         draft_en = case when draft_en is null or draft_en = seed_en then $bf$Room, studio and one-bedroom suite prices cover two adults; two-bedroom suite prices cover four. Children are not counted toward the included number. An extra bed is {extra_bed} per night, covering whoever sleeps on it; it is available in selected room types and chosen when you book. A daily breakfast buffet is served in each property's restaurant 7:00–10:30 am; breakfast is optional and chosen when you book, at {breakfast} per person per day, VAT included; children up to {breakfast_free_age} eat free, children up to {breakfast_child_age} pay {breakfast_child}, and over {breakfast_child_age} the adult price.$bf$ else draft_en end
   where key = 'policy.guests.body';
end;
$bfm$;
